fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    let mut max_val = v[0];
    let mut max_idx = 0;
    
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    let mut min_val = v[start];
    let mut min_idx = start;
    
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If p is the last index, the condition is vacuously true
    if p >= v.len() - 1 {
        return true;
    }
    
    // Find max in prefix [0..=p]
    let (max_prefix, _) = find_max_in_prefix(v, p);
    
    // Find min in suffix [p+1..]
    let (min_suffix, _) = find_min_in_suffix(v, p + 1);
    
    // The barrier property holds if max of prefix is strictly less than min of suffix
    max_prefix < min_suffix
}